select bioaudit.fill_tpl($j$[
{"n":"Aspergillus Galactomannan Antigen","sy":["Galactomannan","GM antigen"],"b":"Serum (or bronchoalveolar lavage fluid)","bs":"RS","a":"Some antibiotics and nutritional products can cause false positives. Antifungal treatment lowers the level and can cause false negatives.","r":"Usually twice a week in people at high risk who are being monitored, such as during chemotherapy, or as your specialist advises.","s":"A raised index supports invasive aspergillosis in people with weakened immune systems. It is read alongside CT scans and other tests.","hi":"invasive aspergillosis, especially in people with a weakened immune system","gl":"A negative result makes invasive aspergillosis less likely, especially when repeated.","gh":"A positive index supports invasive aspergillosis, particularly when repeated or matched by scan findings.","c":["Invasive aspergillosis","Neutropenia","Stem cell or organ transplant"],"f":["Follow infection-prevention advice during chemotherapy","Avoid building sites and compost when your immunity is low"],"x":["Fever that does not respond to antibiotics","Cough","Chest pain","Coughing up blood"],"ug":"Seek urgent medical advice if you have a fever or breathing problems while your immune system is weakened."},
{"n":"Beta-D-Glucan (1→3-β-D-Glucan)","sy":["BDG","1,3-beta-D-glucan"],"b":"S","bs":"IM","a":"Some intravenous immunoglobulin and albumin products, haemodialysis membranes, surgical gauze and certain antibiotics can cause false positives.","r":"T","s":"A raised level supports an invasive fungal infection such as Candida or Pneumocystis. It does not show which fungus is present.","hi":"invasive fungal infection, such as candidaemia or Pneumocystis pneumonia","gl":"A negative result makes many invasive fungal infections unlikely. It does not detect Cryptococcus or Mucorales.","gh":"A raised level supports an invasive fungal infection. Other tests identify the fungus.","c":["Invasive candidiasis","Pneumocystis pneumonia","Invasive aspergillosis"],"x":["Fever that does not respond to antibiotics","Feeling very unwell","Breathlessness"],"f":["Follow infection-prevention advice if your immune system is weakened"],"ug":"Seek urgent medical advice if you have a fever while your immune system is weakened."},
{"n":"Bordetella pertussis Antibody (Anti-PT IgG)","sy":["Anti-PT IgG","Pertussis toxin IgG"],"hi":"recent whooping cough infection, or vaccination in the past year","gl":"A low level makes recent whooping cough unlikely.","gh":"A raised level in someone not vaccinated in the past year suggests recent whooping cough infection."},
{"n":"Borrelia burgdorferi IgG","m":"IGG","cx":"BL","O":"Borrelia (the bacteria that cause Lyme disease)","bs":"IM","y":"IgG antibodies to Borrelia appear several weeks after infection and support a diagnosis of later-stage Lyme disease.","c":["Lyme disease"],"x":["Expanding red rash (erythema migrans)","Fever and aches","Joint pain","Facial weakness"],"f":["Use insect repellent and cover your skin in tick areas","Check for ticks after walks and remove them promptly"],"sy":["Lyme IgG","Borrelia IgG"],"z":["Borrelia burgdorferi IgM","Lyme Disease Serology (Borrelia)"],"t":["A typical erythema migrans rash after a tick bite is treated without waiting for a blood test.","Positive screening results are confirmed with an immunoblot test."],"r":"If the first test is negative but Lyme disease is still suspected, repeat it 4 to 6 weeks later.","ug":"Seek urgent advice if you develop facial weakness, a severe headache, palpitations or fainting after a tick bite."},
{"n":"Borrelia burgdorferi IgM","m":"IGM","cx":"BL","O":"Borrelia (the bacteria that cause Lyme disease)","bs":"IM","y":"IgM antibodies to Borrelia appear 2 to 4 weeks after infection and support a diagnosis of early Lyme disease.","c":["Lyme disease"],"x":["Expanding red rash (erythema migrans)","Fever and aches","Joint pain","Facial weakness"],"f":["Use insect repellent and cover your skin in tick areas","Check for ticks after walks and remove them promptly"],"sy":["Lyme IgM","Borrelia IgM"],"z":["Borrelia burgdorferi IgG","Lyme Disease Serology (Borrelia)"],"t":["Antibodies can be absent in the first weeks after a tick bite, so early tests can be falsely negative.","A positive IgM alone after several weeks of illness can be a false positive."],"r":"If the first test is negative but Lyme disease is still suspected, repeat it 4 to 6 weeks later.","ug":"Seek urgent advice if you develop facial weakness, a severe headache, palpitations or fainting after a tick bite."},
{"n":"Brucella Serology (SAT / ELISA)","sy":["Brucellosis serology","Brucella antibodies"],"hi":"brucellosis, an infection caught from unpasteurised dairy products or infected animals","gl":"A negative result makes brucellosis unlikely, unless the test was taken early in the illness.","gh":"A positive result supports brucellosis. Blood culture can confirm it."},
{"n":"Candida Albicans IgA/IgG/IgM","sy":["Candida antibodies"],"u":"Qualitative or index (laboratory-specific)","rr":{"both":{"normal":["Negative","Not detected","No antibodies to Candida albicans were found."],"high":["Positive","Detected","Antibodies to Candida albicans were found. These are common in healthy people."]}},"gl":"No antibodies to Candida albicans were found.","gh":"Antibodies to Candida albicans were found. Most people carry Candida, so antibodies are common in healthy people and do not prove infection.","z":["Candida Mannan Antigen + Anti-Mannan IgG","Beta-D-Glucan (1→3-β-D-Glucan)"]},
{"n":"Candida albicans IgA","sy":["Candida IgA"],"u":"Qualitative or index (laboratory-specific)","rr":{"both":{"normal":["Negative","Not detected","No IgA antibodies to Candida albicans were found."],"high":["Positive","Detected","IgA antibodies to Candida albicans were found. These are common in healthy people."]}},"gl":"No IgA antibodies to Candida albicans were found.","gh":"IgA antibodies to Candida albicans were found. These are common in healthy people and do not prove infection.","z":["Candida albicans IgG","Candida albicans IgM"]},
{"n":"Candida albicans IgG","sy":["Candida IgG"],"u":"Qualitative or index (laboratory-specific)","rr":{"both":{"normal":["Negative","Not detected","No IgG antibodies to Candida albicans were found."],"high":["Positive","Detected","IgG antibodies to Candida albicans were found. These are common in healthy people."]}},"gl":"No IgG antibodies to Candida albicans were found.","gh":"IgG antibodies to Candida albicans were found. These are common in healthy people and do not prove infection.","z":["Candida albicans IgA","Candida albicans IgM"]},
{"n":"Candida albicans IgM","sy":["Candida IgM"],"u":"Qualitative or index (laboratory-specific)","rr":{"both":{"normal":["Negative","Not detected","No IgM antibodies to Candida albicans were found."],"high":["Positive","Detected","IgM antibodies to Candida albicans were found."]}},"gl":"No IgM antibodies to Candida albicans were found.","gh":"IgM antibodies to Candida albicans were found. This does not on its own prove an active infection.","z":["Candida albicans IgA","Candida albicans IgG"]},
{"n":"Candida Mannan Antigen + Anti-Mannan IgG","sy":["Mannan antigen","Anti-mannan antibodies"],"hi":"invasive candidiasis, particularly when both antigen and antibody are raised","gl":"A negative result makes invasive candidiasis less likely.","gh":"Raised mannan antigen with anti-mannan antibodies supports invasive Candida infection in people at risk."},
{"n":"COVID-19 Spike IgG (Anti-SARS-CoV-2 Spike)","gl":"No antibodies to the SARS-CoV-2 spike protein were found. This does not tell you whether you are protected.","gh":"Antibodies to the spike protein were found. This shows past infection or vaccination, but no level guarantees protection."},
{"n":"Cryptococcal Antigen (CrAg)","sy":["CrAg","Cryptococcus antigen"],"hi":"cryptococcal infection, mainly in people with advanced HIV or a weakened immune system","gl":"A negative result makes cryptococcal infection unlikely.","gh":"A positive result shows cryptococcal infection and needs urgent specialist assessment, including checks for meningitis.","ug":"Seek urgent medical advice if you have a headache, fever, neck stiffness or confusion."},
{"n":"Cytomegalovirus IgG","sy":["CMV IgG"],"u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No IgG antibodies to CMV were found."],"high":["Positive","Detected","IgG antibodies to CMV were found, which shows past infection."]}},"gl":"A negative result means you have not had CMV. This matters in pregnancy and before a transplant.","gh":"A positive result means you have had CMV in the past. The virus stays in the body for life and rarely causes problems in healthy people.","z":["Cytomegalovirus IgM","Cytomegalovirus Serology"]},
{"n":"Cytomegalovirus IgM","sy":["CMV IgM"],"u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No IgM antibodies to CMV were found."],"high":["Positive","Detected","IgM antibodies to CMV were found, which can mean recent infection or reactivation."]}},"gl":"A negative result makes recent CMV infection unlikely.","gh":"A positive result can mean recent CMV infection or reactivation. IgM can stay positive for months, so IgG avidity testing may be needed, especially in pregnancy.","z":["Cytomegalovirus IgG"]},
{"n":"Cytomegalovirus Serology","sy":["CMV serology","CMV antibodies"],"hi":"recent or past CMV infection","gl":"No CMV antibodies were found, so you have not had CMV.","gh":"CMV antibodies were found. IgG alone shows past infection, while IgM suggests recent infection or reactivation."},
{"n":"Dengue Fever Screen","sy":["Dengue NS1 antigen","Dengue antibodies"],"hi":"current or recent dengue infection","gl":"A negative result makes dengue less likely, but timing matters. NS1 antigen works best in the first 5 days of illness and antibodies after that.","gh":"A positive result supports current or recent dengue infection.","ug":"Seek urgent medical advice if you have severe abdominal pain, repeated vomiting, bleeding gums or nose, or drowsiness after travel to a dengue area."},
{"n":"EBNA IgG antibodies","sy":["EBNA-1 IgG","EBV nuclear antigen IgG"],"u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No EBNA IgG was found."],"high":["Positive","Detected","EBNA IgG was found, which usually means past EBV infection."]}},"gl":"A negative EBNA IgG with a positive VCA IgM suggests a recent glandular fever infection.","gh":"A positive EBNA IgG usually means an EBV infection more than 6 to 8 weeks ago.","z":["Epstein-Barr virus capsid antigen IgG","Epstein-Barr virus capsid antigen IgM"]},
{"n":"Echinococcus (Hydatid Cyst) Serology","sy":["Hydatid serology","Echinococcus antibodies"],"hi":"hydatid disease, caused by the tapeworm Echinococcus","gl":"A negative result makes hydatid disease less likely, but some cysts do not trigger antibodies.","gh":"A positive result supports hydatid disease, which is confirmed with imaging."},
{"n":"Epstein-Barr virus capsid antigen IgG","sy":["VCA IgG","EBV VCA IgG"],"u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No VCA IgG was found."],"high":["Positive","Detected","VCA IgG was found, which shows EBV infection at some point."]}},"gl":"A negative result means no past EBV infection, unless the infection is very recent.","gh":"A positive result shows EBV infection at some point. EBNA IgG helps tell recent from past infection.","z":["EBNA IgG antibodies","Epstein-Barr virus capsid antigen IgM"]},
{"n":"Epstein-Barr virus capsid antigen IgM","sy":["VCA IgM","EBV VCA IgM"],"u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No VCA IgM was found."],"high":["Positive","Detected","VCA IgM was found, which suggests recent EBV infection."]}},"gl":"A negative result makes recent glandular fever unlikely.","gh":"A positive result suggests recent EBV infection (glandular fever), especially when EBNA IgG is negative.","z":["EBNA IgG antibodies","Epstein-Barr virus capsid antigen IgG"]},
{"n":"Epstein-Barr Virus PCR","m":"PCR","cx":"BL","O":"Epstein-Barr virus (EBV)","b":"Whole blood or plasma (EDTA)","bs":"IM","y":"EBV DNA in blood helps diagnose and monitor EBV-related disease in people with weakened immune systems, such as after a transplant.","c":["Glandular fever","Post-transplant lymphoproliferative disorder","EBV-related lymphoma"],"x":["Fever","Swollen glands","Sore throat","Tiredness"],"f":["Avoid kissing and sharing drinks during active glandular fever"],"sy":["EBV DNA","EBV viral load","EBV PCR"],"t":["Low levels of EBV DNA can be found in healthy people after infection, so trends matter more than one result."],"z":["Epstein-Barr virus capsid antigen IgM","EBNA IgG antibodies"],"r":"T"},
{"n":"Epstein-Barr Virus Serology","gl":"No EBV antibodies were found, so you have not had EBV infection.","gh":"The antibody pattern shows whether EBV infection is recent or past. VCA IgM with no EBNA IgG suggests recent glandular fever."},
{"n":"Helicobacter pylori Antibodies","a":"Antibodies stay positive for months or years after successful treatment, so they cannot confirm that an infection has cleared.","r":"Do not repeat this test to check whether treatment worked. A breath test or stool antigen test is used instead, at least 4 weeks after antibiotics."},
{"n":"Hepatitis A Serology (HAV IgG / IgM)","gl":"No antibodies to hepatitis A were found. You are not immune and can be vaccinated before travel.","gh":"IgM antibodies mean recent hepatitis A. IgG alone means past infection or vaccination and lifelong immunity."},
{"n":"Hepatitis A: HAV IgM (HAV IgM)","m":"IGM","cx":"HEP","O":"hepatitis A virus","y":"IgM antibodies to hepatitis A confirm a recent infection. It is caught from contaminated food or water and usually clears by itself.","c":["Hepatitis A"],"x":["Yellowing of the skin and eyes (jaundice)","Dark urine","Tiredness","Nausea","Pale stools"],"f":["Get vaccinated before travel to higher-risk countries","Wash hands after using the toilet and before preparing food"],"sy":["HAV IgM","Hepatitis A IgM"],"t":["Close contacts may be offered a vaccine to prevent infection."],"z":["Hepatitis A Serology (HAV IgG / IgM)","ALT"],"r":"Only if your clinician advises it. Liver blood tests are usually repeated until they return to normal."},
{"n":"Hepatitis B Core Antibody (Total)","u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No past or current hepatitis B infection was detected."],"high":["Positive","Detected","Shows past or current hepatitis B infection. Vaccination does not cause a positive result."]}},"gl":"A negative result means you have never been infected with hepatitis B.","gh":"A positive result shows past or current hepatitis B infection. Surface antigen testing shows whether the infection is current.","z":["Hepatitis B Surface Antigen","Hepatitis B Surface Antibody (HBsAb)","Hepatitis B: HB Core IgM (HBc IgM)"]},
{"n":"Hepatitis B Surface Antibody (HBsAb)","gl":"Below 10 mIU/mL means you are not protected against hepatitis B. Vaccination or a booster may be needed.","gh":"10 mIU/mL or above shows protection from vaccination or past infection. Levels above 100 mIU/mL show a good vaccine response."},
{"n":"Hepatitis B Surface Antigen","gl":"A negative result means no current hepatitis B infection was detected.","gh":"A positive result means current hepatitis B infection. If it stays positive for more than 6 months, the infection is chronic and needs specialist care."},
{"n":"Hepatitis B Viral Load (HBV DNA)","sy":["HBV DNA","Hepatitis B DNA"],"hi":"active hepatitis B virus replication","lo":"-","gl":"A low or undetectable level shows the virus is controlled, either naturally or with treatment.","gh":"A high level shows active replication and helps your specialist decide on treatment and liver monitoring.","x":["Often no symptoms","Tiredness","Jaundice","Abdominal discomfort"]},
{"n":"Hepatitis B: HB Core IgM (HBc IgM)","m":"IGM","cx":"HEP","O":"the hepatitis B core antigen","y":"Core IgM antibodies point to a recent (acute) hepatitis B infection. They can also rise during flares of chronic infection.","c":["Acute hepatitis B","Chronic hepatitis B flare"],"sy":["Anti-HBc IgM","HBc IgM"],"t":["Core IgM is the key test to tell a new infection from a long-standing one."],"z":["Hepatitis B Surface Antigen","Hepatitis B Core Antibody (Total)"],"r":"T"},
{"n":"Hepatitis B: HB e Antibodies (HBe Ab)","cx":"HEP","w":"A blood test for antibodies to the hepatitis B e antigen (anti-HBe) in people with hepatitis B.","y":"Anti-HBe usually appears as the virus becomes less active, so it helps your specialist judge the phase of chronic hepatitis B.","u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No anti-HBe was found."],"high":["Positive","Detected","Anti-HBe was found, which often means lower viral activity."]}},"a":"The phase of hepatitis B infection, antiviral treatment and virus strains that do not make e antigen.","s":"Anti-HBe helps stage chronic hepatitis B. Its meaning depends on the e antigen result and viral load.","hi":"a less active phase of hepatitis B","gl":"A negative result in someone with hepatitis B can mean the virus is more active. Viral load testing helps clarify this.","gh":"A positive result usually means the virus is less active, although some strains still replicate. Viral load testing confirms this.","c":["Chronic hepatitis B"],"sy":["Anti-HBe","HBeAb"],"t":["Some hepatitis B strains (precore mutants) stay active despite a positive anti-HBe."],"z":["Hepatitis B: HB e Antigen (HBe Ag)","Hepatitis B Viral Load (HBV DNA)"],"r":"T"},
{"n":"Hepatitis B: HB e Antigen (HBe Ag)","cx":"HEP","w":"A blood test for the hepatitis B e antigen (HBeAg), a protein made when the hepatitis B virus is actively multiplying.","y":"A positive HBeAg means high viral activity and higher infectivity. It helps guide treatment decisions.","u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No HBeAg was found."],"high":["Positive","Detected","HBeAg was found, which shows active viral replication."]}},"a":"The phase of hepatitis B infection, antiviral treatment and virus strains that do not make e antigen.","s":"HBeAg shows active hepatitis B replication. Loss of HBeAg and appearance of anti-HBe usually marks lower activity.","hi":"active hepatitis B replication and higher infectivity","gl":"A negative result often means lower viral activity, but viral load testing is needed to confirm it.","gh":"A positive result shows active viral replication and higher infectivity.","c":["Chronic hepatitis B","Acute hepatitis B"],"sy":["HBeAg"],"t":["Babies born to mothers with a positive HBeAg are at highest risk and need vaccine and immunoglobulin at birth."],"z":["Hepatitis B: HB e Antibodies (HBe Ab)","Hepatitis B Viral Load (HBV DNA)"],"r":"T"},
{"n":"Hepatitis C Antibody","gl":"A negative result means no hepatitis C infection was detected. Repeat it 3 months after a recent possible exposure.","gh":"A positive result shows past or current infection. An HCV RNA test shows whether the virus is still present. Modern treatment cures over 95% of people."},
{"n":"Hepatitis C RNA Viral Load (HCV RNA PCR)","gl":"Undetectable HCV RNA means the virus is not present. After treatment this confirms cure.","gh":"Detectable HCV RNA means current infection. A course of tablets for 8 to 12 weeks cures most people."},
{"n":"Hepatitis E Serology (HEV IgG/IgM) and PCR","sy":["HEV serology","Hepatitis E antibodies"],"hi":"recent or past hepatitis E infection","gl":"No evidence of hepatitis E infection was found.","gh":"IgM or HEV RNA suggests recent infection, often from undercooked pork. IgG alone suggests past infection."},
{"n":"Herpes Simplex Virus 1 and 2 IgM","m":"IGM","cx":"BL","O":"herpes simplex virus","bs":"SK","y":"IgM antibodies to herpes simplex can appear after a first infection, but the test is unreliable and not recommended for diagnosing herpes.","c":["Genital herpes","Cold sores"],"x":["Painful blisters or sores","Tingling before sores appear","Flu-like symptoms with a first episode"],"f":["Avoid sex while you have sores","Use condoms"],"sy":["HSV IgM"],"t":["UK guidance does not recommend HSV IgM testing because false positives are common. PCR on a sore is preferred."],"z":["Herpes Simplex Virus 1 (HSV-1) PCR","Herpes Simplex Virus 2 (HSV-2) PCR"],"r":"S"},
{"n":"Herpes simplex virus 1 IgG","m":"IGG","cx":"BL","O":"herpes simplex virus type 1 (HSV-1)","bs":"SK","y":"HSV-1 IgG shows past infection with the virus that most often causes cold sores. Most adults have been infected.","c":["Cold sores","Genital herpes"],"x":["Usually no symptoms","Cold sores","Genital sores"],"f":["Avoid kissing and oral sex when you have a cold sore","Use condoms"],"sy":["HSV-1 IgG","HSV1 antibodies"],"t":["A positive result cannot tell whether the infection is oral or genital."],"z":["Herpes simplex virus 2 IgG","Herpes Simplex Virus 1 (HSV-1) PCR"],"r":"O"},
{"n":"Herpes simplex virus 2 IgG","m":"IGG","cx":"BL","O":"herpes simplex virus type 2 (HSV-2)","bs":"SK","y":"HSV-2 IgG shows past infection with the virus that most often causes genital herpes. Many people with HSV-2 have never noticed symptoms.","c":["Genital herpes"],"x":["Usually no symptoms","Genital sores"],"f":["Avoid sex while you have sores","Use condoms"],"sy":["HSV-2 IgG","HSV2 antibodies"],"t":["Low positive HSV-2 IgG results can be false positives and may need confirmation."],"z":["Herpes simplex virus 1 IgG","Herpes Simplex Virus 2 (HSV-2) PCR"],"r":"O"},
{"n":"Herpes Simplex Virus IgG (Type 1 & 2)","gl":"No antibodies to herpes simplex were found, so you have not been infected, unless infection was very recent.","gh":"Antibodies show infection at some point. Type-specific results show whether it was HSV-1, HSV-2 or both, but not where the infection is or when it happened."},
{"n":"HIV 1 & 2 Antibody/Antigen","gl":"A negative result means no HIV was detected. If you had a possible exposure in the past 45 days, repeat the test 45 days after that exposure.","gh":"A reactive result needs a confirmatory test. HIV is now a manageable long-term condition with treatment.","ug":"If you think you have been exposed to HIV in the past 72 hours, get post-exposure prophylaxis (PEP) from a sexual health clinic or A&E straight away."},
{"n":"HIV Antibodies","m":"SER","cx":"HIV","O":"HIV-1 and HIV-2","w":"A blood test for antibodies to HIV-1 and HIV-2, which the body makes after HIV infection.","y":"It detects established HIV infection. Antibody-only tests take longer to turn positive than combined antigen and antibody tests.","s":"A reactive result needs confirmation with further tests. A confirmed positive result means HIV infection.","gl":"No HIV antibodies were found. Antibody-only tests can miss infection in the 3 months after exposure.","gh":"HIV antibodies were found. The result will be confirmed with further tests before a diagnosis is made.","hi":"HIV infection","c":["HIV infection"],"sy":["Anti-HIV antibodies","HIV Ab"],"t":["Combined antigen and antibody tests detect infection earlier and are preferred in the UK."],"r":"Repeat 3 months after a possible exposure if this is an antibody-only test. Test at least once a year if you are at ongoing risk."},
{"n":"HIV Viral Load (HIV-1 RNA PCR)","sy":["HIV RNA","HIV-1 viral load","HIV PCR"],"hi":"active HIV replication, such as untreated infection or treatment failure","lo":"-","gl":"An undetectable viral load means HIV treatment is working. People with an undetectable viral load cannot pass HIV on through sex.","gh":"A detectable viral load means HIV is replicating. Your HIV team will review your treatment.","x":["Often no symptoms","Recurrent infections","Weight loss","Night sweats"]},
{"n":"HIV-1 antibodies","m":"SER","cx":"HIV","O":"HIV-1","w":"A blood test for antibodies to HIV-1, the most common type of HIV worldwide.","y":"It helps diagnose HIV-1 infection, and reactive results are confirmed with further tests.","s":"A reactive result needs confirmation. A confirmed positive result means HIV-1 infection.","gl":"No HIV-1 antibodies were found. Testing too soon after exposure can miss infection.","gh":"HIV-1 antibodies were found. The result will be confirmed with further tests before a diagnosis is made.","hi":"HIV-1 infection","c":["HIV infection"],"sy":["Anti-HIV-1"],"t":["Reactive screening results are always confirmed with a second, different test before diagnosis."],"r":"Repeat 3 months after a possible exposure. Test at least once a year if you are at ongoing risk."},
{"n":"HIV-2 antibodies","m":"SER","cx":"HIV","O":"HIV-2","w":"A blood test for antibodies to HIV-2, a less common type of HIV found mainly in West Africa.","y":"HIV-2 progresses more slowly than HIV-1 and needs different treatment choices, so telling the types apart matters.","s":"A reactive result needs confirmation at a specialist laboratory.","gl":"No HIV-2 antibodies were found.","gh":"HIV-2 antibodies were found. Specialist testing confirms the result and the HIV type.","hi":"HIV-2 infection","c":["HIV infection"],"sy":["Anti-HIV-2"],"t":["HIV-2 viral load tests differ from HIV-1 tests, so specialist laboratories are used."],"r":"Repeat 3 months after a possible exposure. Test at least once a year if you are at ongoing risk."},
{"n":"HTLV-1/2 Serology","sy":["HTLV antibodies","HTLV-1/2 antibodies"],"hi":"HTLV-1 or HTLV-2 infection","gl":"A negative result means no HTLV infection was detected.","gh":"A positive screening result needs confirmation. Most people with HTLV never develop related disease, but specialist follow-up is advised."},
{"n":"Lyme Disease Serology (Borrelia)","sy":["Lyme serology","Borrelia antibodies"],"b":"S","bs":"IM","a":"Time since the tick bite, early antibiotic treatment and the test method. Antibodies can take 4 to 6 weeks to appear.","r":"If negative but symptoms continue, repeat 4 to 6 weeks later. Antibodies can stay positive for years after treatment, so testing does not confirm cure.","s":"A positive screening test confirmed by an immunoblot supports Lyme disease when it fits your symptoms and history of tick exposure.","hi":"Lyme disease, especially when confirmed by an immunoblot","gl":"A negative result makes Lyme disease less likely, unless the test was taken in the first weeks after a bite.","gh":"A positive result supports Lyme disease. Positive screening results are confirmed by an immunoblot.","c":["Lyme disease","Lyme neuroborreliosis","Lyme arthritis"],"f":["Use insect repellent and cover your skin in tick areas","Check for ticks after walks and remove them promptly"],"x":["Expanding red rash (erythema migrans)","Fever and aches","Joint pain","Facial weakness"],"ug":"Seek urgent advice if you develop facial weakness, a severe headache, palpitations or fainting after a tick bite."},
{"n":"Malaria Screen (Rapid Antigen / Film)","sy":["Malaria test","Malaria film"],"b":"WB","bs":"HA","a":"Timing of the sample, antimalarial medicines and low parasite levels. One negative test does not rule out malaria.","r":"If malaria is still suspected after a negative result, repeat the test every 12 to 24 hours until three tests have been done.","s":"Any positive result means malaria and needs same-day treatment. The film shows the species and the percentage of infected red cells.","hi":"malaria infection","gl":"No malaria parasites were found. Malaria cannot be excluded until three tests over 48 to 72 hours are negative.","gh":"Malaria parasites were found. This is a medical emergency that needs same-day treatment.","c":["Malaria"],"x":["Fever and sweats","Chills","Headache","Muscle aches","Vomiting or diarrhoea"],"f":["Take antimalarial tablets as prescribed when travelling","Use insect repellent and bed nets","Seek medical help for any fever within a year of travel"],"ug":"Seek same-day medical care for any fever during or after travel to a malaria area, even months later."},
{"n":"Measles IgG","m":"IGG","cx":"IMMUNE","O":"measles virus","y":"Measles IgG shows immunity from vaccination or past infection. It is useful before pregnancy, travel or work in healthcare.","c":["Measles"],"x":["Usually none if immune","Fever and rash if infected"],"f":["Two doses of MMR vaccine give lasting protection"],"sy":["Measles antibodies","Measles immunity"],"t":["If you are not immune, two doses of MMR vaccine at least a month apart give protection."],"gl":"A negative result means no immunity to measles was detected. Two doses of MMR vaccine are recommended.","gh":"A positive result shows immunity to measles from vaccination or past infection.","z":["Mumps IgG","Rubella IgG Antibody"],"ug":"If you think you have measles, phone your GP or NHS 111 before attending, to avoid spreading it.","im":"If you are not immune, MMR vaccination is free on the NHS at any age."},
{"n":"Mumps IgG","m":"IGG","cx":"IMMUNE","O":"mumps virus","y":"Mumps IgG shows immunity from vaccination or past infection.","c":["Mumps","Orchitis"],"x":["Usually none if immune","Painful swelling of the glands below the ears if infected"],"f":["Two doses of MMR vaccine give the best protection"],"sy":["Mumps antibodies","Mumps immunity"],"t":["Immunity after MMR vaccination can wane, so outbreaks still occur in vaccinated young adults."],"gl":"A negative result means no immunity to mumps was detected. MMR vaccination is recommended if you have not had two doses.","gh":"A positive result shows immunity to mumps from vaccination or past infection.","z":["Measles IgG","Rubella IgG Antibody"]},
{"n":"Mycoplasma pneumoniae Serology","sy":["Mycoplasma antibodies","M. pneumoniae serology"],"b":"S","bs":"RS","a":"Antibodies take 1 to 2 weeks to appear. IgM can persist for months, and false positives occur.","r":"A second sample 2 to 4 weeks after the first can show a rising antibody level.","s":"A positive IgM or a rising IgG supports recent Mycoplasma pneumoniae infection.","hi":"recent Mycoplasma pneumoniae infection","gl":"A negative result makes recent infection less likely, unless taken early in the illness.","gh":"A positive result supports recent infection. PCR on a throat swab gives a faster answer.","c":["Atypical pneumonia"],"f":["Wash your hands often","Cover coughs and sneezes"],"x":["Persistent dry cough","Fever","Sore throat","Tiredness"],"ug":"Seek urgent medical advice if you have difficulty breathing, chest pain, confusion or a high fever that does not settle."},
{"n":"p24 Antigen","m":"AG","cx":"HIV","O":"HIV p24","w":"A blood test for the HIV p24 protein, which appears in the blood within 2 to 3 weeks of HIV infection, before antibodies develop.","y":"It helps detect very early HIV infection and is part of combined fourth-generation HIV tests.","c":["HIV infection","Acute HIV infection"],"sy":["HIV p24 antigen","p24 Ag"],"t":["p24 can become undetectable once antibodies form, so it is used with antibody testing."],"r":"Repeat 45 days after a possible exposure if the first test was earlier."},
{"n":"Parvovirus B19 IgG","m":"IGG","cx":"BL","O":"parvovirus B19","bs":"HA","y":"Parvovirus B19 IgG shows past infection and immunity. It matters in pregnancy, as infection can affect the baby.","c":["Slapped cheek syndrome (fifth disease)","Aplastic crisis","Fetal anaemia"],"x":["Bright red cheeks","Lacy rash","Joint pain","Mild fever"],"f":["Wash your hands often","If you are pregnant and in contact with slapped cheek syndrome, speak to your midwife or GP"],"sy":["Parvovirus IgG","B19 IgG"],"t":["A positive IgG before an exposure in pregnancy means you are immune and the baby is protected."],"z":["Parvovirus B19 IgM"],"ug":"If you are pregnant and exposed to slapped cheek syndrome, contact your midwife or GP promptly.","r":"S"},
{"n":"Parvovirus B19 IgM","m":"IGM","cx":"BL","O":"parvovirus B19","bs":"HA","y":"Parvovirus B19 IgM suggests a recent infection, which is usually mild but matters in pregnancy and in people with blood disorders.","c":["Slapped cheek syndrome (fifth disease)","Aplastic crisis","Fetal anaemia"],"x":["Bright red cheeks","Lacy rash","Joint pain","Mild fever"],"f":["Wash your hands often","If you are pregnant and in contact with slapped cheek syndrome, speak to your midwife or GP"],"sy":["Parvovirus IgM","B19 IgM"],"t":["In pregnancy, a positive IgM leads to specialist monitoring of the baby."],"z":["Parvovirus B19 IgG"],"ug":"If you are pregnant and exposed to slapped cheek syndrome, contact your midwife or GP promptly.","r":"S"},
{"n":"Parvovirus B19 Serology","sy":["Parvovirus serology"],"b":"S","bs":"HA","a":"Timing after exposure. IgM appears about 10 days after infection and can last for months.","r":"If tested soon after an exposure in pregnancy, a repeat test 2 to 4 weeks later may be needed.","s":"IgM suggests recent infection, and IgG alone shows past infection and immunity.","hi":"recent or past parvovirus B19 infection","gl":"No antibodies were found, so you have not had parvovirus B19 and are not immune.","gh":"IgG alone means past infection and immunity. IgM suggests recent infection.","c":["Slapped cheek syndrome (fifth disease)","Aplastic crisis","Fetal anaemia"],"f":["Wash your hands often","If you are pregnant and in contact with slapped cheek syndrome, speak to your midwife or GP"],"x":["Bright red cheeks","Lacy rash","Joint pain","Mild fever"],"ug":"If you are pregnant and exposed to slapped cheek syndrome, contact your midwife or GP promptly."},
{"n":"Q Fever (Coxiella burnetii) Serology","sy":["Coxiella burnetii antibodies","Q fever antibodies"],"b":"S","bs":"MU","a":"Antibodies take 2 to 3 weeks to appear. Phase 1 and phase 2 antibodies help tell acute from chronic infection.","r":"A second sample 2 to 4 weeks after the first can confirm acute infection. People treated for Q fever are usually monitored for a year or more.","s":"Raised phase 2 antibodies suggest acute Q fever. High phase 1 IgG can point to chronic infection, such as of the heart valves.","hi":"Q fever infection, usually caught from farm animals","gl":"A negative result makes Q fever unlikely, unless taken early in the illness.","gh":"A positive result supports Q fever. The pattern of phase 1 and phase 2 antibodies shows whether it is acute or chronic.","c":["Q fever","Q fever endocarditis","Post-Q fever fatigue"],"f":["Take care around lambing and calving","Avoid unpasteurised milk"],"x":["Flu-like illness","High fever","Headache","Cough"]},
{"n":"QuantiFERON-TB Gold Plus (IGRA)","b":"Whole blood (QuantiFERON tubes)","bs":"IM","a":"Recent exposure (it can take 8 weeks to turn positive), a weakened immune system, steroids or immunosuppressive drugs, and sample handling.","r":"If exposure was within the past 8 weeks and the first result is negative, repeat 8 weeks after the last exposure.","s":"A positive result shows TB infection, either latent or active. A chest X-ray and clinical assessment tell them apart.","hi":"TB infection, either latent or active","gl":"A negative result makes TB infection unlikely, but does not rule it out in people with weakened immune systems.","gh":"A positive result shows infection with TB bacteria. Most people have latent TB, which is not infectious but can be treated to prevent active disease.","c":["Latent tuberculosis","Active tuberculosis"],"f":["Complete any course of TB treatment","Tell your clinician about TB exposure before starting biologic medicines"],"x":["Usually none in latent TB","Cough lasting more than 3 weeks","Night sweats","Weight loss","Fever"],"ug":"Seek urgent medical advice if you are coughing up blood or have breathlessness, fever and weight loss."},
{"n":"Rubella IgG Antibody","b":"S","bs":"IM","a":"Time since vaccination or infection, and the laboratory method. Some vaccinated people have low levels that are not detected.","r":"Usually tested once. Routine rubella testing in pregnancy stopped in the UK, so checking your MMR vaccine history is advised instead.","s":"A positive result shows immunity to rubella from vaccination or past infection.","hi":"immunity to rubella","gl":"Below 10 IU/mL suggests no immunity. MMR vaccination is recommended, but not during pregnancy.","gh":"10 IU/mL or more shows immunity to rubella.","c":["Rubella (German measles)","Congenital rubella syndrome"],"f":["Check you have had two doses of MMR vaccine before pregnancy"],"x":["Usually none if immune","Mild fever and rash if infected"],"ug":"If you are pregnant and exposed to a rash illness, contact your midwife or GP promptly.","im":"If you are not immune, have MMR vaccination before pregnancy and avoid pregnancy for one month afterwards."},
{"n":"Rubella IgM","m":"IGM","cx":"BL","O":"rubella virus","bs":"IM","y":"Rubella IgM suggests a recent rubella infection, which matters most in early pregnancy.","c":["Rubella (German measles)","Congenital rubella syndrome"],"x":["Fine pink rash","Swollen glands behind the ears","Mild fever","Joint pain"],"f":["Make sure you have had two doses of MMR vaccine"],"sy":["Rubella IgM antibodies"],"t":["False positive rubella IgM results occur, so positive results are confirmed by a reference laboratory."],"z":["Rubella IgG Antibody"],"r":"Only if your clinician advises it, usually after a rash illness or a contact in pregnancy.","ug":"If you are pregnant and exposed to a rash illness, contact your midwife or GP promptly."},
{"n":"Schistosoma Serology (IgG ELISA)","sy":["Bilharzia serology","Schistosoma antibodies"],"b":"S","bs":"MU","a":"Antibodies take 6 to 12 weeks after exposure to appear and can stay positive for years after treatment.","r":"Test at least 12 weeks after your last freshwater exposure. Retesting after treatment is not useful because antibodies persist.","s":"A positive result shows exposure to schistosomiasis, a parasite caught from freshwater in Africa and other tropical areas.","hi":"exposure to schistosomiasis (bilharzia)","gl":"A negative result taken at least 12 weeks after exposure makes schistosomiasis unlikely.","gh":"A positive result shows exposure. Treatment with praziquantel is usually recommended.","c":["Schistosomiasis (bilharzia)"],"f":["Avoid swimming or wading in freshwater lakes and rivers in affected areas"],"x":["Itchy rash after swimming","Fever and cough weeks later","Blood in urine","Abdominal pain"]},
{"n":"Strongyloides Serology (IgG ELISA)","sy":["Strongyloides antibodies"],"b":"S","bs":"DG","a":"Antibodies can take weeks to appear. Steroids and a weakened immune system lower antibody levels.","r":"Usually tested once. A repeat 6 to 12 months after treatment can show falling antibody levels.","s":"A positive result shows Strongyloides infection, which can persist for decades and become dangerous with steroid treatment.","hi":"Strongyloides infection","gl":"A negative result makes Strongyloides infection unlikely.","gh":"A positive result shows infection, which should be treated, especially before steroids or immunosuppressive treatment.","c":["Strongyloidiasis","Hyperinfection syndrome"],"f":["Wear shoes on soil in tropical regions"],"x":["Often no symptoms","Itchy, moving rash","Abdominal pain","Diarrhoea"],"ug":"Seek urgent medical advice if you develop fever, breathlessness or severe abdominal pain while taking steroids."},
{"n":"Syphilis (Treponema Serology)","b":"S","bs":"MU","a":"Time since infection, as antibodies take up to 12 weeks to appear, and past treated syphilis, as treponemal antibodies usually stay positive for life.","r":"Repeat 12 weeks after a possible exposure if the first test was earlier. After treatment, RPR is checked to confirm a fall in levels.","s":"A reactive treponemal test shows current or past syphilis. RPR or VDRL levels show whether infection is active.","hi":"current or past syphilis infection","gl":"A non-reactive result makes syphilis unlikely, unless exposure was in the past 12 weeks.","gh":"A reactive result shows current or past infection. Further tests confirm it, and syphilis is cured with penicillin.","c":["Syphilis","Neurosyphilis","Congenital syphilis"],"f":["Use condoms with new or casual partners","Test after a new partner and when you have symptoms","Tell recent partners if you test positive so they can be tested"],"x":["Painless sore (chancre)","Rash on the palms or soles","Swollen glands","Flu-like symptoms"],"ug":"Seek urgent medical advice if you have changes in vision or hearing, a severe headache or confusion."},
{"n":"Toxocara Serology (IgG ELISA)","sy":["Toxocara antibodies"],"b":"S","bs":"MU","a":"Antibodies can stay positive for years, so a positive result may reflect old exposure.","r":"S","s":"A positive result shows exposure to Toxocara, a roundworm from dog and cat faeces.","hi":"exposure to Toxocara roundworms","gl":"A negative result makes toxocariasis unlikely.","gh":"A positive result shows exposure. It is more likely to be relevant with raised eosinophils or eye symptoms.","c":["Toxocariasis","Ocular toxocariasis"],"f":["Worm pets regularly","Wash hands after handling soil or pets","Pick up dog faeces"],"x":["Often no symptoms","Cough or wheeze","Abdominal pain","Blurred vision in one eye"],"ug":"Seek urgent medical advice if you have sudden changes in vision."},
{"n":"Toxoplasma IgG","m":"IGG","cx":"BL","O":"Toxoplasma gondii","bs":"MU","y":"Toxoplasma IgG shows past infection, which is common and usually harmless. It matters in pregnancy and for people with weakened immune systems.","c":["Toxoplasmosis","Congenital toxoplasmosis"],"x":["Usually no symptoms","Swollen glands","Flu-like illness"],"f":["Cook meat thoroughly","Wash fruit and vegetables","Wear gloves for gardening and cat litter, especially in pregnancy"],"sy":["Toxoplasma antibodies IgG","Toxo IgG"],"t":["A positive IgG from before pregnancy means the baby is protected from a new infection."],"z":["Toxoplasma IgM","Toxoplasma Serology"],"r":"S"},
{"n":"Toxoplasma IgM","m":"IGM","cx":"BL","O":"Toxoplasma gondii","bs":"MU","y":"Toxoplasma IgM can point to a recent infection, but it can stay positive for over a year. Avidity testing helps date the infection in pregnancy.","c":["Toxoplasmosis","Congenital toxoplasmosis"],"x":["Usually no symptoms","Swollen glands","Flu-like illness"],"f":["Cook meat thoroughly","Wash fruit and vegetables","Wear gloves for gardening and cat litter, especially in pregnancy"],"sy":["Toxoplasma antibodies IgM","Toxo IgM"],"t":["In pregnancy, a positive IgM is confirmed at a reference laboratory before any decisions are made."],"z":["Toxoplasma IgG","Toxoplasma Serology"],"r":"S"},
{"n":"Toxoplasma Serology","sy":["Toxoplasma antibodies","Toxoplasmosis test"],"b":"S","bs":"MU","a":"IgM can persist for months to years, and false positives occur. Avidity testing helps date the infection.","r":"In pregnancy, a repeat sample after 2 to 3 weeks may be needed to date the infection.","s":"IgG shows past infection. IgM with low-avidity IgG suggests infection within the last few months.","hi":"recent or past Toxoplasma infection","gl":"No antibodies were found, so you have not had toxoplasmosis and can take steps to avoid it in pregnancy.","gh":"Antibodies were found. The IgM and IgG pattern shows whether infection is recent or past.","c":["Toxoplasmosis","Congenital toxoplasmosis"],"f":["Cook meat thoroughly","Wash fruit and vegetables","Wear gloves for gardening and cat litter, especially in pregnancy"],"x":["Usually no symptoms","Swollen glands","Flu-like illness"]},
{"n":"Varicella zoster IgG","b":"S","bs":"IM","a":"Time since infection or vaccination, a weakened immune system and the test method. Recent immunoglobulin treatment can cause a false positive.","r":"Usually tested once, for example before pregnancy, a transplant or work in healthcare.","s":"A positive result shows immunity to chickenpox from past infection or vaccination.","hi":"immunity to chickenpox","gl":"A negative result means you are not immune to chickenpox. Tell your clinician if you are exposed, especially in pregnancy.","gh":"A positive result shows immunity to chickenpox.","c":["Chickenpox","Shingles"],"f":["Ask about chickenpox vaccination if you are not immune"],"ug":"If you are pregnant, not immune and exposed to chickenpox or shingles, contact your GP or midwife the same day."},
{"n":"Varicella zoster IgM","m":"IGM","cx":"BL","O":"varicella zoster virus","bs":"SK","y":"Varicella zoster IgM supports a recent chickenpox or shingles infection, although the diagnosis is usually made from the rash.","c":["Chickenpox","Shingles"],"x":["Itchy spotty rash that blisters","Fever","Painful band of rash (shingles)"],"f":["Stay away from pregnant women, newborns and people with weakened immunity while infectious"],"sy":["VZV IgM"],"t":["PCR on fluid from a blister is the most reliable test for active chickenpox or shingles."],"z":["Varicella zoster IgG"],"r":"S"},
{"n":"Zika virus IgG","m":"IGG","cx":"BL","O":"Zika virus","bs":"MU","y":"Zika IgG shows past infection with Zika virus, a mosquito-borne infection that can harm babies in pregnancy.","c":["Zika virus infection"],"x":["Rash","Mild fever","Red eyes","Joint pain"],"f":["Avoid mosquito bites in affected areas","Follow advice on safer sex and delaying pregnancy after travel"],"sy":["Zika IgG"],"t":["Zika IgG cross-reacts with dengue antibodies, so positive results need confirmation."],"z":["Zika virus IgM"],"r":"S"},
{"n":"Zika virus IgM","m":"IGM","cx":"BL","O":"Zika virus","bs":"MU","y":"Zika IgM suggests a recent infection. Results are read with travel dates and confirmed by a reference laboratory.","c":["Zika virus infection","Congenital Zika syndrome"],"x":["Rash","Mild fever","Red eyes","Joint pain"],"f":["Avoid mosquito bites in affected areas","Follow advice on safer sex and delaying pregnancy after travel"],"sy":["Zika IgM"],"t":["Cross-reaction with dengue is common, so positive results need confirmation."],"z":["Zika virus IgG"],"r":"S"},
{"n":"Zika Virus Serology (IgG / IgM)","sy":["Zika antibodies"],"b":"S","bs":"MU","a":"Timing after travel or symptoms, and cross-reaction with antibodies to dengue and other flaviviruses or vaccines.","r":"Follow specialist advice. In pregnancy, testing and repeat testing depend on travel dates and symptoms.","s":"IgM suggests recent Zika infection, but cross-reaction with dengue is common, so positive results need confirmation.","hi":"recent or past Zika infection","gl":"A negative result makes recent Zika infection unlikely if the test was taken at the right time after travel.","gh":"A positive result needs confirmation at a reference laboratory because of cross-reaction with dengue.","c":["Zika virus infection","Congenital Zika syndrome"],"f":["Avoid mosquito bites in affected areas","Follow advice on safer sex and delaying pregnancy after travel"],"x":["Rash","Mild fever","Red eyes","Joint pain"],"ug":"If you are pregnant and have travelled to a Zika-risk area, tell your midwife or GP."}
